        localT = Math.max(0, Math.min(1, localT));
        const s = 0.5;
        const eased = localT * localT * ((s + 1) * localT - s);
        return eased * BASE_OFFSET;
    } else if (phase === 'IN') {
        const startT = d * 0.2;
        if (t < startT) return BASE_OFFSET;
        let localT = (t - startT) * 1.5;
